#include <string>
#include <sstream> // For string streams

int main() {
    // Using string streams for formatting
    std::stringstream ss;
    int number = 42;
    ss << "The answer is: " << number;
    std::string answerString = ss.str();
    std::cout << answerString << std::endl; // Output: The answer is: 42

    return 0;
}

```


